import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Checks","description":"","frontmatter":{},"headers":[],"relativePath":"checks.md","filePath":"checks.md"}'),o={name:"checks.md"};function n(s,t,i,h,c,l){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="checks" tabindex="-1">Checks <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;Checks&quot;">​</a></h1><p><code>npm run audit</code> checks the components against the rules of kata. It has two parts: a reading of the sources, and a measurement of the examples in a browser. <code>npm run check</code> runs it with the other checks of the repository (<a href="https://github.com/sakuzu/kata/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING</a> lists them).</p><h2 id="the-sources" tabindex="-1">The sources <a class="header-anchor" href="#the-sources" aria-label="Permalink to &quot;The sources&quot;">​</a></h2><p><code>scripts/lint-components.mjs</code> reads the styles of the components in <code>src/svelte</code>.</p><ul><li>Spacing, type and colour take a token, never a raw length or colour.</li><li><code>padding</code> takes the pad scale and <code>gap</code> the gap scale.</li><li>Only the components that hold text in a control (Button, Toggle, TextInput and the other controls, a mark such as Badge, a list item, a pair or a table cell), at a container&#39;s edge (Text) or next to a line (Section, SectionHeader) trim text.</li><li>No negative distance, no outer margin on a component&#39;s root (the layouts, Icon and Prose aside), no <code>@media</code> for a width and no <code>:has()</code> other than the next sibling.</li><li>Every custom property a component reads is defined.</li><li>Every component is exported, has an example and has a page here or in the <a href="./workbench/README">Workbench</a> chapter.</li></ul><h2 id="the-examples" tabindex="-1">The examples <a class="header-anchor" href="#the-examples" aria-label="Permalink to &quot;The examples&quot;">​</a></h2><p>The audit builds the examples and opens each one in Chromium, served by Vite&#39;s preview server. Every example is measured at three widths (1440, 768 and 390px), at the default and the largest text size, in the dark and the light theme, and with an English and a Japanese root. Every visible element inside the example is measured; a finding fails the audit.</p><table tabindex="0"><thead><tr><th>Rule</th><th>What is measured</th></tr></thead><tbody><tr><td>space</td><td>Padding and gaps are 0 or a step of the scale</td></tr><tr><td>margin</td><td>Outer margins appear only in Prose and Block, never negative</td></tr><tr><td>type</td><td>Font sizes are type roles; line heights are a step of the scale</td></tr><tr><td>border</td><td>Borders are 0, 1 or 2px and solid, so no border of the browser</td></tr><tr><td>height</td><td>An element with <code>data-h</code> has the height of that token</td></tr><tr><td>trim</td><td>Text is trimmed in a control, at a container&#39;s edge or at a line</td></tr><tr><td>trim-clip</td><td>Trimmed text keeps its vertical overflow, so no ink is cut</td></tr><tr><td>cursor</td><td>What can be pressed shows the pointer</td></tr><tr><td>contrast</td><td>Text reaches 7:1 on its surface (4.5:1 when disabled or dimmed)</td></tr><tr><td>focus-halo</td><td>A text field shows a 2px ring on focus</td></tr><tr><td>double-rule</td><td>No two lines run along one edge</td></tr><tr><td>double-inset</td><td>A container with padding never sits in another one</td></tr><tr><td>bundle-edge</td><td>Text in an unpadded container or surface keeps pad-md</td></tr><tr><td>inner-gap</td><td>In a padded container, neighbours are no further than the edge</td></tr><tr><td>box-touch</td><td>A control never touches the padded edge of its container</td></tr><tr><td>box-gap</td><td>Controls stacked vertically are at least md apart</td></tr><tr><td>rule-gap</td><td>A line is as far from what is above as from what is below</td></tr><tr><td>head-gap</td><td>A section header&#39;s head is pad-md from its content</td></tr><tr><td>head-near</td><td>A group&#39;s head is nearer its content than the group above</td></tr><tr><td>page-head-gap</td><td>A page&#39;s head is pad-lg from its content</td></tr><tr><td>section-head-gap</td><td>A section&#39;s head is gap-lg from its content</td></tr><tr><td>tabs-gap</td><td>Content under Tabs is gap-lg away (not in an unpadded container)</td></tr><tr><td>read-row</td><td>A list item that is only read has a line or a surface</td></tr><tr><td>overlap</td><td>The children of a layout do not overlap</td></tr><tr><td>crush</td><td>Text is never squeezed narrower than two characters</td></tr><tr><td>fixed-frame</td><td>A Shell or an embedded root is not the frame of fixed elements</td></tr></tbody></table><p>Distances are measured from the edge of what is visible: the outline of a component with a line or a surface, a line, the inner edge of a container, or the ink of text. A line along one side of a component only is an edge on that side only; from the other side the distance runs to what is inside it (the text of tabs with a line along their bottom). An element marked <code>data-kata-skip</code> (drawn by the browser or by another library) is not measured.</p><p>head-gap allows one exception: flush content under a head with an action keeps pad-md above it, so that the action that hangs below the head does not reach the first row, and its distance from the head may grow by that padding and the action&#39;s overhang. head-near allows the same group to lie further from its head by the action&#39;s overhang.</p>',10)])])}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
